const items = $input.all();
const weekStr = 'W' + Math.ceil((new Date().getDate()) / 7) + '_' + (new Date().getMonth() + 1);

return items.map(item => {
  const d = item.json;
  const token = Buffer.from((d.email || 'emp') + '_' + Date.now()).toString('base64').substring(0, 16);
  return {
    json: {
      ...d,
      surveyWeek: weekStr,
      surveyToken: token,
      magicLink: 'http://localhost:3000/engagement/survey?token=' + token + '&week=' + weekStr,
      preferredChannel: d.preferredChannel || 'EMAIL'
    }
  };
});

const totalEmployees = 50;
const totalResponses = 42;
const promoters = 26;
const passives = 10;
const detractors = 6;

const enpsScore = Math.round(((promoters - detractors) / totalResponses) * 100);
const responseRate = Math.round((totalResponses / totalEmployees) * 100);

return {
  totalEmployees,
  totalResponses,
  responseRate: responseRate + '%',
  promoters,
  detractors,
  enpsScore,
  healthStatus: enpsScore >= 40 ? 'XUẤT SẮC' : (enpsScore >= 20 ? 'TỐT' : 'CẦN CHÚ Ý'),
  calculatedAt: new Date().toISOString()
};
